extern "C" { fn readb(addr: *const c_void) -> u8; fn writeb(value: u8, addr: *mut c_void); fn udelay(usecs: u32); }

pub unsafe fn plx9080_abort_dma(iobase: *mut c_void, channel: u32) -> i32 {
    let dma_cs_addr = (iobase as *mut u8).add(PLX_REG_DMACSR(channel) as usize) as *mut c_void;
    let timeout: u32 = 10000; let mut dma_status = readb(dma_cs_addr);
    if dma_status & PLX_DMACSR_ENABLE == 0 { return 0; }
    let mut i=0; while dma_status & PLX_DMACSR_DONE != 0 && i < timeout { udelay(1); dma_status=readb(dma_cs_addr); i+=1; }
    if i==timeout { return -110; }
    writeb(PLX_DMACSR_ABORT, dma_cs_addr); dma_status=readb(dma_cs_addr); i=0;
    while dma_status & PLX_DMACSR_DONE == 0 && i < timeout { udelay(1); dma_status=readb(dma_cs_addr); i+=1; }
    if i==timeout { return -110; } 0
}

